/**
 * Features as a list of disclosures: icon and title in the summary, the text when open. Axes: expand (first: the
 * first one is open, none: all closed), media (none, image: a picture beside the list), tone, density.
 */
import { type ReactNode } from "react";
import { Disclosure } from "../primitives/disclosure/disclosure";
import { Summary } from "../primitives/disclosure/summary";
import { Group } from "../primitives/group/group";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { MediaFrame } from "../components/media-frame";
import { SectionFrame } from "../components/section-frame";
import { tpl } from "../utils";
import type { Feature } from "./feature-grid.types";

export type FeatureAccordionProps = {
  id: string;
  title: string;
  features: Feature[];
  expand?: "first" | "none";
  media?: "none" | "image";
  multiple?: boolean;
  tone?: "default" | "muted";
  density?: "default" | "compact";
};

export function FeatureAccordion({
  id,
  title,
  features,
  expand = "first",
  media = "none",
  multiple = false,
  tone = "default",
  density = "default",
}: FeatureAccordionProps) {
  return (
    <SectionFrame
      id={id}
      title={title}
      tone={tone}
      density={density}
      layout={(((media as string) === "image") ? "split" : "stack")}
      media={{ show: ((media as string) === "image") }}
      aside={(
        <MediaFrame alt={title} ratio="4/3" />
      )}
    >
      <Stack gap="0" align="stretch" data-testid="items">
        {(features ?? []).map((f, i) => (
          <Disclosure key={f.id}
            variant="item"
            name={(multiple ? undefined : tpl("{0}-accordion", (id ?? "accordion")))}
            open={(((expand as string) === "first") && (i === 0))}
            data-testid="item"
          >
            <Summary variant="item">
              <Group gap="4" align="center">
                <LucideIcon name={f.icon} size={20} />
                <Text size="base" weight="semibold">
                  {f.title}
                </Text>
              </Group>
            </Summary>
            <Text size="sm" className="pb-4 text-muted-foreground">
              {f.text}
            </Text>
          </Disclosure>
        ))}
      </Stack>
    </SectionFrame>
  );
}
